#!/bin/sh
# Generated by FWShift: a Google Cloud network firewall policy, created with gcloud. Read the report first: what is
# not written is listed there.
#
#   DRY_RUN=1 sh THIS_FILE                              prints the commands; needs no access to Google Cloud
#   GCLOUD_OPTS='--project my-project' sh THIS_FILE     creates the policy and its rules
#
# The policy is associated with no network: nothing changes for any traffic until you associate it:
#   gcloud compute network-firewall-policies associations create --firewall-policy fwshift --network NETWORK --global-firewall-policy
# It decides every connection of that network. Set the network's enforcement order to BEFORE_CLASSIC_FIREWALL, or
# the VPC firewall rules of the network decide first. A policy of the same name stops the script before anything is
# created; a command gcloud refuses stops it where it is (delete the policy and run it again).
set -u
DRY_RUN="${DRY_RUN:-}"
GCLOUD_OPTS="${GCLOUD_OPTS:-}"
POLICY=fwshift
fail() { printf 'FAILED: %s\n' "$*" >&2; exit 1; }
run() {
  if [ -n "$DRY_RUN" ]; then printf 'gcloud' >&2; printf ' %s' "$@" >&2; printf '\n' >&2; return 0; fi
  gcloud "$@" $GCLOUD_OPTS --quiet >/dev/null || fail "gcloud $1 $2 $3 $4"
}
if [ -z "$DRY_RUN" ] && gcloud compute network-firewall-policies describe "$POLICY" --global $GCLOUD_OPTS >/dev/null 2>&1; then
  fail "a network firewall policy named $POLICY exists already; nothing was created"
fi

run compute network-firewall-policies create "$POLICY" --global '--description=Generated by FWShift; review the conversion report before associating it'

run compute network-firewall-policies rules create 1000 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=192.0.2.66/32,203.0.113.0/25 --layer4-configs=all --enable-logging '--description=Block Bad'
run compute network-firewall-policies rules create 1010 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=192.0.2.66/32,203.0.113.0/25 --layer4-configs=all --enable-logging '--description=Block Bad'
run compute network-firewall-policies rules create 1020 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=all --description=fwshift-default-deny
run compute network-firewall-policies rules create 1030 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=all --description=fwshift-default-deny
run compute network-firewall-policies rules create 1040 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=::/0 --dest-ip-ranges=::/0 --layer4-configs=all --description=fwshift-default-deny
run compute network-firewall-policies rules create 1050 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=::/0 --dest-ip-ranges=::/0 --layer4-configs=all --description=fwshift-default-deny

# Not written:
#   Admin SSH: the source of the rule is in zone Trusted, and a rule of Google Cloud names no zone: give the networks behind Trusted with --zone-network; the destination of the rule is in zone External, and a rule of Google Cloud names no zone: give the networks behind External with --zone-network
#   Web Out: the source of the rule is in zone Trusted, Guests, DMZ, and a rule of Google Cloud names no zone: give the networks behind Trusted, Guests, DMZ with --zone-network; the destination of the rule is in zone External, and a rule of Google Cloud names no zone: give the networks behind External with --zon
#   Web In: the source of the rule is in zone External, and a rule of Google Cloud names no zone: give the networks behind External with --zone-network
#   Mail In: the source of the rule is in zone External, and a rule of Google Cloud names no zone: give the networks behind External with --zone-network
#   DMZ Updates: schedule 'Business Hours' is not converted; the rule would apply at all times; the source of the rule is in zone DMZ, and a rule of Google Cloud names no zone: give the networks behind DMZ with --zone-network; the destination 'Update-Site.1.alm' holds members only its platform knows; a rule of Googl
#   Guests Out: the source of the rule is in zone Guests, and a rule of Google Cloud names no zone: give the networks behind Guests with --zone-network; the destination of the rule is in zone External, and a rule of Google Cloud names no zone: give the networks behind External with --zone-network
#   Staff Only: source user match Staff is not converted; the source of the rule is in zone Trusted, and a rule of Google Cloud names no zone: give the networks behind Trusted with --zone-network
#   Ping: the source of the rule is in zone Trusted, Guests, and a rule of Google Cloud names no zone: give the networks behind Trusted, Guests with --zone-network
#   Lab Tunnel: the source of the rule is in zone Lab, and a rule of Google Cloud names no zone: give the networks behind Lab with --zone-network; the destination of the rule is in zone External, and a rule of Google Cloud names no zone: give the networks behind External with --zone-network

echo 'Done. Associate the policy with the network when you are ready; until then nothing changes.' >&2
